/// A fully qualified `spec://` address (`SpecAddress`), carried field-by-field;
/// conversion re-checks the fields against `raw`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SpecAddress {
    /// Tree path segments; empty means the whole document.
    pub anchor: Vec<String>,

    pub authority: Authority,

    /// Document path under the `spec/` root, `/`-joined, genre included.
    pub doc_path: String,

    /// The address exactly as written, including any `~rN`.
    pub raw: String,

    /// Spec-unit revision pin (`~rN`); absent when unpinned.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pinned_r: Option<u32>,
}
